import AccessorArray = require( '@stdlib/array/base/accessor' );
import gpartitionqs = require( './index' );


// TESTS //

// The function returns a numeric array...
{
	const x = new Float64Array( 10 );

	gpartitionqs( x.length, 2, 1, x, 1 ); // $ExpectType Float64Array
	gpartitionqs( x.length, 2, 1, new AccessorArray( x ), 1 ); // $ExpectType AccessorArray<number>
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	const x = new Float64Array( 10 );

	gpartitionqs( '10', 2, 1, x, 1 ); // $ExpectError
	gpartitionqs( true, 2, 1, x, 1 ); // $ExpectError
	gpartitionqs( false, 2, 1, x, 1 ); // $ExpectError
	gpartitionqs( null, 2, 1, x, 1 ); // $ExpectError
	gpartitionqs( undefined, 2, 1, x, 1 ); // $ExpectError
	gpartitionqs( [], 2, 1, x, 1 ); // $ExpectError
	gpartitionqs( {}, 2, 1, x, 1 ); // $ExpectError
	gpartitionqs( ( x: number ): number => x, 2, 1, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	const x = new Float64Array( 10 );

	gpartitionqs( x.length, '10', 1, x, 1 ); // $ExpectError
	gpartitionqs( x.length, true, 1, x, 1 ); // $ExpectError
	gpartitionqs( x.length, false, 1, x, 1 ); // $ExpectError
	gpartitionqs( x.length, null, 1, x, 1 ); // $ExpectError
	gpartitionqs( x.length, undefined, 1, x, 1 ); // $ExpectError
	gpartitionqs( x.length, [], 1, x, 1 ); // $ExpectError
	gpartitionqs( x.length, {}, 1, x, 1 ); // $ExpectError
	gpartitionqs( x.length, ( x: number ): number => x, 1, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number...
{
	const x = new Float64Array( 10 );

	gpartitionqs( x.length, 2, '10', x, 1 ); // $ExpectError
	gpartitionqs( x.length, 2, true, x, 1 ); // $ExpectError
	gpartitionqs( x.length, 2, false, x, 1 ); // $ExpectError
	gpartitionqs( x.length, 2, null, x, 1 ); // $ExpectError
	gpartitionqs( x.length, 2, undefined, x, 1 ); // $ExpectError
	gpartitionqs( x.length, 2, [], x, 1 ); // $ExpectError
	gpartitionqs( x.length, 2, {}, x, 1 ); // $ExpectError
	gpartitionqs( x.length, 2, ( x: number ): number => x, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a numeric array...
{
	const x = new Float64Array( 10 );

	gpartitionqs( x.length, 2, 1, 10, 1 ); // $ExpectError
	gpartitionqs( x.length, 2, 1, '10', 1 ); // $ExpectError
	gpartitionqs( x.length, 2, 1, true, 1 ); // $ExpectError
	gpartitionqs( x.length, 2, 1, false, 1 ); // $ExpectError
	gpartitionqs( x.length, 2, 1, null, 1 ); // $ExpectError
	gpartitionqs( x.length, 2, 1, undefined, 1 ); // $ExpectError
	gpartitionqs( x.length, 2, 1, [ '1' ], 1 ); // $ExpectError
	gpartitionqs( x.length, 2, 1, {}, 1 ); // $ExpectError
	gpartitionqs( x.length, 2, 1, ( x: number ): number => x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fifth argument which is not a number...
{
	const x = new Float64Array( 10 );

	gpartitionqs( x.length, 2, 1, x, '10' ); // $ExpectError
	gpartitionqs( x.length, 2, 1, x, true ); // $ExpectError
	gpartitionqs( x.length, 2, 1, x, false ); // $ExpectError
	gpartitionqs( x.length, 2, 1, x, null ); // $ExpectError
	gpartitionqs( x.length, 2, 1, x, undefined ); // $ExpectError
	gpartitionqs( x.length, 2, 1, x, [] ); // $ExpectError
	gpartitionqs( x.length, 2, 1, x, {} ); // $ExpectError
	gpartitionqs( x.length, 2, 1, x, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = new Float64Array( 10 );

	gpartitionqs(); // $ExpectError
	gpartitionqs( x.length ); // $ExpectError
	gpartitionqs( x.length, 2 ); // $ExpectError
	gpartitionqs( x.length, 2, 1 ); // $ExpectError
	gpartitionqs( x.length, 2, 1, x ); // $ExpectError
	gpartitionqs( x.length, 2, 1, x, 1, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a numeric array...
{
	const x = new Float64Array( 10 );

	gpartitionqs.ndarray( x.length, 2, 1, x, 1, 0 ); // $ExpectType Float64Array
	gpartitionqs.ndarray( x.length, 2, 1, new AccessorArray( x ), 1, 0 ); // $ExpectType AccessorArray<number>
}

