	gpartitionqs.ndarray( x.length, 2, 1 ); // $ExpectError
	gpartitionqs.ndarray( x.length, 2, 1, x ); // $ExpectError
	gpartitionqs.ndarray( x.length, 2, 1, x, 1 ); // $ExpectError
	gpartitionqs.ndarray( x.length, 2, 1, x, 1, 0, 10 ); // $ExpectError
